{
  "duration_weeks": 12,
  "phases": [
    {
      "name": "Foundations",
      "weeks": 4,
      "focus": "Establish movement patterns and baseline strength with bodyweight and minimal equipment."
    },
    {
      "name": "Progression",
      "weeks": 4,
      "focus": "Increase work capacity and introduce progression for primary lifts using bodyweight and doorway bar."
    },
    {
      "name": "Consolidation",
      "weeks": 2,
      "focus": "Solidify technique, improve relative strength, and prep for higher-intensity work."
    },
    {
      "name": "Peak/Return Load",
      "weeks": 2,
      "focus": "Capstone phase to maximize strength within space/equipment constraints and plan for maintenance."
    }
  ],
  "weekly_template": {
    "days_per_week": 4,
    "day_types": [
      "Push",
      "Pull",
      "Leg/Core",
      "Accessibility/Recovery"
    ]
  },
  "non_negotiables": [
    "Safety first: perform warm-up prior to each session.",
    "Complete movements within available space in a small flat.",
    "Use a doorway pull-up bar only; no other external equipment.",
    "Maintain neutral spine; avoid rounding during loaded positions.",
    "Progression must be controlled; focus on technique before load/volume.",
    "If pain or discomfort occurs, stop and reassess form; seek guidance.",
    "Rest days distributed; ensure 1–2 days of recovery per week."
  ]
}
